/**
 * A file attached to a prompt, shown as a chip (`design/components/attachment-chip.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/attachment-chip.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { mergeProps, onCleanup, onMount, type JSX } from 'solid-js'

import {
  Icon,
  agentMember,
  claimSlot,
  elementRef,
  formatBytes,
  scope,
  type Defaults,
  type IconRole,
} from '@polymorph/solid'
import styles from '@polymorph/recipes/ai/attachment-chip.module.css'
import Button from '../controls/Button'
import Link from '../controls/Link'
import Spinner from '../structure/Spinner'

export type AttachmentStatus = 'uploading' | 'done' | 'error'

export interface AttachmentChipProps {
  /**
   * The file's URL, which makes the name a link that opens in a new tab (Link's `external`).
   */
  href?: string
  /**
   * The leading mark, `document` by default, or `table` or `browser` when the app knows the
   * kind.
   */
  icon?: IconRole
  /**
   * The app's text for a failure, which the chip never writes itself.
   */
  message?: string
  /**
   * The file's name, ellipsed when the row is narrow.
   */
  name: string
  /**
   * Shows the remove button when supplied, and is omitted in a sent message, where removal is
   * over.
   */
  onRemove?: () => void
  /**
   * The remove button's accessible name (default `Remove {name}`), which apps pass to localize.
   */
  removeLabel?: string
  /**
   * The size in bytes, formatted by the engine's `formatBytes`, as FileUpload's rows are, so
   * sizes match in both places.
   */
  size?: number
  /**
   * The upload status, where `done` is the rest state.
   */
  status?: 'error' | 'uploading' | 'done'
  /**
   * The status announced while the file uploads (default `{name}: uploading`), which apps pass
   * to localize.
   */
  uploadingLabel?: string
}

/** A file attached to a prompt, shown as a chip. */
export default function AttachmentChip(given: AttachmentChipProps): JSX.Element {
  const props = mergeProps(
    { status: 'done', icon: 'document' } as Defaults<AttachmentChipProps, 'status' | 'icon'>,
    claimSlot(given),
  )
  return scope(() => {
    const chip = elementRef<HTMLElement>()
    const file = elementRef<HTMLElement>()
    let release1: (() => void) | undefined
    const effect1 = () => {
      release1?.()
      const ran = agentMember({
        member: 'AttachmentChip',
        element: () => file.value,
        state: () => ({ name: props.name, status: props.status }),
        actions: {
          remove: () =>
            (() => {
              if (!(props.onRemove !== undefined))
                throw new Error('The chip records a sent file and has no remove control.')
              props.onRemove?.()
            })(),
        },
        withholds: () => chip.value,
      })
      release1 = () => {
        ran()
      }
    }
    onMount(effect1)
    onCleanup(() => release1?.())
    return (
      <span
        class={styles.chip}
        data-status={props.status}
        data-member="attachment-chip"
        ref={chip.attach}
      >
        {/* mark */}
        <span class={styles.mark}>
          {props.status === 'uploading' ? (
            <Spinner size="sm" label={props.uploadingLabel ?? `${props.name}: uploading`} />
          ) : props.status === 'error' ? (
            <Icon name="error" size="sm" />
          ) : (
            <Icon name={props.icon} size="sm" />
          )}
        </span>
        {/* body */}
        <span class={styles.body}>
          {/* name */}
          <span class={styles.name} ref={file.attach}>
            {props.href === undefined ? (
              props.name
            ) : (
              <Link href={props.href} external={true}>
                {props.name}
              </Link>
            )}
          </span>
          {props.size !== undefined && props.status !== 'error' ? (
            <span class={styles.meta}>{formatBytes(props.size)}</span>
          ) : null}
          {props.status === 'error' && props.message !== undefined ? (
            <span class={styles.message}>{props.message}</span>
          ) : null}
        </span>
        {props.onRemove !== undefined ? (
          <Button
            variant="ghost"
            tone="neutral"
            size="sm"
            iconOnly={true}
            icon="close"
            label={props.removeLabel ?? `Remove ${props.name}`}
            onClick={() => props.onRemove?.()}
          />
        ) : null}
      </span>
    )
  })
}
